def get_me(api_key=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0421000" if __import__("os").path.isdir("./environment_mix/0421000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    api_clients = _load("api_clients.json")
    counters = _load("usage_counters.json")
    reqs = _load("weather_requests.json")

    def _bucket_start(dt, bucket_type):
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _get_usage(client_id):
        m = _bucket_start(now, "minute").isoformat()
        d = _bucket_start(now, "day").isoformat()
        cur_min = next((r for r in counters if r.get("client_id") == client_id and r.get("bucket_type") == "minute" and r.get("bucket_start") == m), None)
        cur_day = next((r for r in counters if r.get("client_id") == client_id and r.get("bucket_type") == "day" and r.get("bucket_start") == d), None)
        return cur_min, cur_day

    # Authenticate only if api_key provided; match against client-visible stored value (id).
    # (api_key_hash is not usable for plaintext comparison per contract.)
    client = None
    if api_key is None:
        return _err("UNAUTHORIZED", "API key required.")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    api_key = api_key.strip()

    for c in api_clients:
        if c.get("id") == api_key:
            client = c
            break
    if client is None:
        # Optionally allow direct match to api_key_hash only if caller passes that exact stored value
        for c in api_clients:
            if c.get("api_key_hash") is not None and c.get("api_key_hash") == api_key:
                client = c
                break
    if client is None:
        return _err("UNAUTHORIZED", "Invalid API key.")

    # Record call dynamics: model get_me as a weather_requests entry? Schema restricts tool_name enum.
    # Therefore, we must still update observable dynamics via usage_counters only (schema has no audit log for get_me).
    # Enforce rate/quota as well to keep consistent with service limits.
    client_id = client.get("id")
    if not isinstance(client.get("per_minute_limit"), int) or not isinstance(client.get("daily_quota_requests"), int):
        return _err("INTERNAL_ERROR", "Client quota configuration invalid.")

    minute_iso = _bucket_start(now, "minute").isoformat()
    day_iso = _bucket_start(now, "day").isoformat()

    def _find_or_create_usage(bucket_type, bucket_start_iso):
        for r in counters:
            if r.get("client_id") == client_id and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bucket_start_iso:
                return r
        rid = f"uc_{uuid.uuid4().hex}"
        row = {
            "id": rid,
            "client_id": client_id,
            "bucket_type": bucket_type,
            "bucket_start": bucket_start_iso,
            "request_count": 0,
            "served_count": 0,
            "failed_count": 0,
            "cache_hit_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(row)
        return row

    uc_min = _find_or_create_usage("minute", minute_iso)
    uc_day = _find_or_create_usage("day", day_iso)

    would_min = uc_min["request_count"] + 1
    would_day = uc_day["request_count"] + 1
    per_minute_limit = int(client.get("per_minute_limit"))
    daily_quota = int(client.get("daily_quota_requests"))

    if client.get("status") in ("suspended", "deleted"):
        uc_min["request_count"] = would_min
        uc_day["request_count"] = would_day
        uc_min["failed_count"] += 1
        uc_day["failed_count"] += 1
        uc_min["updated_at"] = now_iso
        uc_day["updated_at"] = now_iso
        _save("usage_counters.json", counters)
        return _err("UNAUTHORIZED", "Client is not active.", http_status=403)

    if (per_minute_limit >= 0 and would_min > per_minute_limit) or (daily_quota >= 0 and would_day > daily_quota):
        uc_min["request_count"] = would_min
        uc_day["request_count"] = would_day
        uc_min["failed_count"] += 1
        uc_day["failed_count"] += 1
        uc_min["updated_at"] = now_iso
        uc_day["updated_at"] = now_iso
        _save("usage_counters.json", counters)
        return _err("RATE_LIMIT", "Too many requests.", http_status=429)

    uc_min["request_count"] = would_min
    uc_day["request_count"] = would_day
    uc_min["served_count"] += 1
    uc_day["served_count"] += 1
    uc_min["updated_at"] = now_iso
    uc_day["updated_at"] = now_iso
    _save("usage_counters.json", counters)

    cur_min, cur_day = _get_usage(client_id)

    # Infer "scopes" from tool availability; no explicit schema, so expose allowed tools.
    scopes = ["get_nowcast_observation", "get_nowcast_forecast", "get_short_term_forecast"]

    # Lightweight recent activity
    recent = []
    for r in reversed(reqs[-50:]):
        if r.get("client_id") == client_id:
            recent.append({
                "id": r.get("id"),
                "tool_name": r.get("tool_name"),
                "status": r.get("status"),
                "http_status": r.get("http_status"),
                "requested_at": r.get("requested_at"),
                "cache_hit": r.get("cache_hit"),
            })
        if len(recent) >= 10:
            break

    return {
        "client": {
            "id": client.get("id"),
            "client_name": client.get("client_name"),
            "client_type": client.get("client_type"),
            "status": client.get("status"),
            "limits": {
                "per_minute_limit": per_minute_limit,
                "daily_quota_requests": daily_quota,
            },
            "scopes": scopes,
            "last_seen_ip": client.get("last_seen_ip"),
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
        },
        "usage": {
            "minute_bucket": cur_min,
            "day_bucket": cur_day,
        },
        "recent_requests": recent,
        "latency_ms": int((time.time() - t0) * 1000),
        "now": now_iso,
    }

def create_api_client(client_name, client_type, daily_quota_requests, per_minute_limit, status=None, **_extra):
    import json, os, datetime, secrets, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0421000" if __import__("os").path.isdir("./environment_mix/0421000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # Validate inputs (tool surface)
    if not isinstance(client_name, str) or not client_name.strip():
        return _err("VALIDATION_ERROR", "client_name must be a non-empty string")
    if not isinstance(client_type, str) or client_type not in ("server", "mobile", "web", "internal", "partner"):
        return _err("VALIDATION_ERROR", "client_type must be one of server, mobile, web, internal, partner")
    if not isinstance(daily_quota_requests, int) or daily_quota_requests < 0 or daily_quota_requests > 1000000:
        return _err("VALIDATION_ERROR", "daily_quota_requests must be an integer between 0 and 1000000")
    if not isinstance(per_minute_limit, int) or per_minute_limit < 0 or per_minute_limit > 60000:
        return _err("VALIDATION_ERROR", "per_minute_limit must be an integer between 0 and 60000")
    if status is None:
        status = "active"
    if status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of active, suspended, deleted")

    # Map tool types into datastore enum for api_clients.client_type
    type_map = {
        "internal": "internal",
        "server": "api_key",
        "mobile": "api_key",
        "web": "api_key",
        "partner": "api_key",
    }
    store_client_type = type_map.get(client_type)
    if store_client_type is None:
        return _err("VALIDATION_ERROR", "Unsupported client_type")

    clients = _load("api_clients.json")

    # IMPORTANT: The datastore schema does NOT require unique(client_name); only unique(api_key_hash).
    # So do not reject duplicates of client_name.

    # Create API key and store hash (not used for auth in this offline store)
    api_key_plain = "kw_" + secrets.token_urlsafe(24)
    api_key_hash = hashlib.sha256(api_key_plain.encode("utf-8")).hexdigest()

    # Ensure unique(api_key_hash) where not null
    existing_hashes = set()
    for c in clients:
        if isinstance(c, dict) and c.get("api_key_hash"):
            existing_hashes.add(c.get("api_key_hash"))
    tries = 0
    while api_key_hash in existing_hashes and tries < 5:
        api_key_plain = "kw_" + secrets.token_urlsafe(24)
        api_key_hash = hashlib.sha256(api_key_plain.encode("utf-8")).hexdigest()
        tries += 1
    if api_key_hash in existing_hashes:
        return _err("CONFLICT", "Could not generate a unique api_key_hash")

    now = _now()
    new_id = f"kwc_cli_{uuid.uuid4().hex}"

    row = {
        "id": new_id,
        "client_name": client_name.strip(),
        "client_type": store_client_type,
        "api_key_hash": api_key_hash,
        "status": status,
        "daily_quota_requests": int(daily_quota_requests),
        "per_minute_limit": int(per_minute_limit),
        "last_seen_ip": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    clients.append(row)
    _save("api_clients.json", clients)

    # Return plaintext API key (vendor behavior)
    return {
        "api_key": api_key_plain,
        "api_client": row,
    }

def update_api_client(id, client_name=None, daily_quota_requests=None, per_minute_limit=None, status=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0421000" if __import__("os").path.isdir("./environment_mix/0421000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    if client_name is not None and (not isinstance(client_name, str) or not client_name.strip()):
        return _err("VALIDATION_ERROR", "client_name must be a non-empty string")
    if daily_quota_requests is not None:
        if not isinstance(daily_quota_requests, int) or daily_quota_requests < 0 or daily_quota_requests > 1000000:
            return _err("VALIDATION_ERROR", "daily_quota_requests must be an integer between 0 and 1000000")
    if per_minute_limit is not None:
        if not isinstance(per_minute_limit, int) or per_minute_limit < 0 or per_minute_limit > 60000:
            return _err("VALIDATION_ERROR", "per_minute_limit must be an integer between 0 and 60000")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of active, suspended, deleted")

    clients = _load("api_clients.json")
    idx = None
    for i, c in enumerate(clients):
        if isinstance(c, dict) and c.get("id") == id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "api_client not found")

    cur = clients[idx]
    cur_status = cur.get("status")

    # Deleted cannot be changed at all
    if cur_status == "deleted":
        if any(v is not None for v in (client_name, daily_quota_requests, per_minute_limit, status)):
            return _err("CONFLICT", "cannot modify a deleted client")

    # Status transition rules
    if status is not None and status != cur_status:
        allowed = {
            "active": set(["suspended", "deleted"]),
            "suspended": set(["active", "deleted"]),
            "deleted": set(),
        }
        if cur_status not in allowed or status not in allowed[cur_status]:
            return _err("INVALID_TRANSITION", f"Invalid status transition: {cur_status} -> {status}")

    # NOTE: Do NOT enforce unique client_name; not in schema constraints.
    changed = False
    if client_name is not None and client_name.strip() != cur.get("client_name"):
        cur["client_name"] = client_name.strip()
        changed = True
    if daily_quota_requests is not None and int(daily_quota_requests) != cur.get("daily_quota_requests"):
        cur["daily_quota_requests"] = int(daily_quota_requests)
        changed = True
    if per_minute_limit is not None and int(per_minute_limit) != cur.get("per_minute_limit"):
        cur["per_minute_limit"] = int(per_minute_limit)
        changed = True
    if status is not None and status != cur_status:
        cur["status"] = status
        changed = True

    if not changed:
        # No success without effect
        return _err("CONFLICT", "No changes to apply")

    cur["updated_at"] = _iso(_now())
    clients[idx] = cur
    _save("api_clients.json", clients)
    return {"api_client": cur}

def list_weather_requests(client_id=None, tool_name=None, status=None, cache_hit=None, from_requested_at=None, to_requested_at=None, page_size=None, page_token=None, order_by=None, **_extra):
    import json, os, datetime, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0421000" if __import__("os").path.isdir("./environment_mix/0421000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate filters
    if client_id is not None and (not isinstance(client_id, str) or not client_id.strip()):
        return _err("VALIDATION_ERROR", "client_id must be a non-empty string")
    if tool_name is not None and tool_name not in ("get_nowcast_observation", "get_short_term_forecast", "get_nowcast_forecast"):
        return _err("VALIDATION_ERROR", "tool_name invalid")
    if status is not None and status not in ("received", "served", "failed"):
        return _err("VALIDATION_ERROR", "status invalid")
    if cache_hit is not None and not isinstance(cache_hit, bool):
        return _err("VALIDATION_ERROR", "cache_hit must be boolean")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 200")
    if order_by is None:
        order_by = "requested_at_desc"
    if order_by not in ("requested_at_desc", "requested_at_asc", "created_at_desc", "created_at_asc"):
        return _err("VALIDATION_ERROR", "order_by invalid")
    if page_token is not None and (not isinstance(page_token, str) or not page_token):
        return _err("VALIDATION_ERROR", "page_token must be a non-empty string")

    def _parse_iso(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 string")
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be ISO-8601")
    fr = _parse_iso(from_requested_at, "from_requested_at")
    if isinstance(fr, dict) and "error" in fr:
        return fr
    to = _parse_iso(to_requested_at, "to_requested_at")
    if isinstance(to, dict) and "error" in to:
        return to
    if fr and to and to < fr:
        return _err("VALIDATION_ERROR", "to_requested_at must be >= from_requested_at")

    # Decode page token
    start = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                return _err("VALIDATION_ERROR", "invalid page_token")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                return _err("VALIDATION_ERROR", "invalid page_token")
        except Exception:
            return _err("VALIDATION_ERROR", "invalid page_token")

    rows = _load("weather_requests.json")

    # Filter
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if client_id is not None and r.get("client_id") != client_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        if cache_hit is not None and r.get("cache_hit") != cache_hit:
            continue
        if fr or to:
            try:
                rdt = datetime.datetime.fromisoformat(str(r.get("requested_at", "")).replace("Z", "+00:00"))
                if rdt.tzinfo is None:
                    rdt = rdt.replace(tzinfo=datetime.timezone.utc)
                rdt = rdt.astimezone(datetime.timezone.utc)
            except Exception:
                # If malformed timestamp in store, skip row rather than crash
                continue
            if fr and rdt < fr:
                continue
            if to and rdt > to:
                continue
        out.append(r)

    # Sort
    key_field = "requested_at" if order_by.startswith("requested_at") else "created_at"
    reverse = order_by.endswith("_desc")

    def _sort_key(r):
        v = r.get(key_field)
        try:
            dt = datetime.datetime.fromisoformat(str(v).replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    out.sort(key=_sort_key, reverse=reverse)

    total = len(out)
    page = out[start:start + page_size]
    next_offset = start + page_size
    has_more = next_offset < total
    next_token = None
    if has_more:
        next_token = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "weather_requests": page,
        "total": total,
        "page_size": page_size,
        "next_page_token": next_token,
        "has_more": has_more,
    }
